items.inputSchema:
{
  "type": "object",
  "properties": {
    "tender_id": {
      "type": "string",
      "description": "The id of the tender to open, for example \"T-2026-014\". Call list_tenders first if you do not have one."
    }
  },
  "required": [
    "tender_id"
  ],
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "tender_id": {
      "type": "string",
      "description": "Restrict to one tender, for example \"T-2026-014\". Omit for all of them."
    },
    "status": {
      "type": "string",
      "enum": [
        "open",
        "answered"
      ],
      "description": "Restrict to questions still open, or to those already answered."
    }
  },
  "required": [],
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "category": {
      "type": "string",
      "description": "Restrict to one trade category, for example \"wall\", \"metal\", \"wood\", \"ceiling\", \"prep\" or \"labour\"."
    },
    "query": {
      "type": "string",
      "description": "Free text. Matched against the search terms and the original wording of each entry, ignoring case and German umlauts."
    }
  },
  "required": [],
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "tender_id": {
      "type": "string",
      "description": "The tender to price, for example \"T-2026-014\"."
    },
    "oz": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Item numbers to propose prices for, for example [\"03.04\",\"04.02\"]. Omit for every position of the tender."
    }
  },
  "required": [
    "tender_id"
  ],
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "tender_id": {
      "type": "string",
      "description": "The tender whose bid is being priced, for example \"T-2026-014\"."
    },
    "prices": {
      "type": "array",
      "minItems": 1,
      "maxItems": 50,
      "description": "The rows to write, one per position. Between one and fifty.",
      "items": {
        "type": "object",
        "properties": {
          "oz": {
            "type": "string",
            "description": "The item number of the position, for example \"02.01\"."
          },
          "unit_price": {
            "type": "number",
            "minimum": 0,
            "maximum": 1000000,
            "description": "The price of one unit, in euro. Must equal the price of the price book line named in price_book_id."
          },
          "price_book_id": {
            "type": "string",
            "description": "The price book line this price comes from, copied from a proposal's based_on.price_book_id, for example PB-A-004. A price with no source is refused."
          },
          "note": {
            "type": "string",
            "description": "An optional short remark stored with the row."
          }
        },
        "required": [
          "oz",
          "unit_price",
          "price_book_id"
        ],
        "additionalProperties": false
      }
    }
  },
  "required": [
    "tender_id",
    "prices"
  ],
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "tender_id": {
      "type": "string",
      "description": "The tender whose bid should be checked, for example \"T-2026-014\"."
    }
  },
  "required": [
    "tender_id"
  ],
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "steps": {
      "type": "integer",
      "minimum": 1,
      "maximum": 20,
      "description": "How many writes to take back, newest first. Defaults to one."
    }
  },
  "required": [],
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "tender_id": {
      "type": "string",
      "description": "The tender whose bid should be handed in, for example \"T-2026-014\"."
    },
    "confirm": {
      "type": "boolean",
      "description": "false returns a summary and does nothing. true asks the person to confirm; it does not submit by itself."
    }
  },
  "required": [
    "tender_id",
    "confirm"
  ],
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "oz": {
      "type": "string",
      "description": "The item number the question is about, for example \"02.04\". Leave empty for a question about the tender as a whole."
    },
    "question": {
      "type": "string",
      "description": "The question itself, at most 500 characters. Write it as a professional question to the client."
    }
  },
  "required": [
    "question"
  ]
}
